// Monta o pacote do BI público (Captação – Publicação do BI) a partir das linhas das tabelas.
// Só a lista permitida de campos sai daqui; o resto da linha (motivo, texto_fonte, identidade, duplicata_de,
// tentativas, avaliações) nunca entra no pacote. A lista é conferida contra bi/gerar.py por bi/testes/test_campos.py.

var CAMPOS_OPORTUNIDADES = ['chave', 'titulo_oficial', 'titulo', 'ofertante', 'tipo_oportunidade', 'tipo_instrumento', 'publico_elegivel', 'papel_modal', 'abrangencia', 'regiao', 'prazo', 'valor', 'areas_modal', 'link_edital_oficial', 'url', 'resumo', 'fonte', 'data_captura', 'linha_base'];
var CAMPOS_FONTES = ['nome', 'abrangencia', 'ultima_coleta', 'ultima_coleta_ok'];

function paraTexto(v) {
  if (v === null || v === undefined) return '';
  if (v instanceof Date) return v.toISOString();
  return String(v);
}

// Entrada: { oportunidades, fontes (linhas das tabelas), id, geradoEm (ISO), modo ('publicar' | 'previa') }
function montarPacote(o) {
  var ops = (o.oportunidades || []).filter(function (r) {
    return r && r.situacao_triagem === 'aprovada' && r.chave && !r.duplicata_de;
  }).map(function (r) {
    var s = {};
    CAMPOS_OPORTUNIDADES.forEach(function (k) {
      if (k === 'linha_base') s[k] = r[k] === true;
      else s[k] = paraTexto(r[k]);
    });
    return s;
  });
  var fontes = (o.fontes || []).filter(function (f) { return f && f.nome && f.ativa !== false; }).map(function (f) {
    var st = paraTexto(f.ultimo_status);
    // erro = a leitura falhou; "ok" e "alerta" (leitura boa, sem candidatos) contam como leitura ok. O texto do status não sai.
    return { nome: paraTexto(f.nome), abrangencia: paraTexto(f.abrangencia), ultima_coleta: paraTexto(f.ultima_coleta), ultima_coleta_ok: !!f.ultima_coleta && !/^erro/i.test(st) };
  });
  return { id: o.id, gerado_em: o.geradoEm, modo: o.modo === 'publicar' ? 'publicar' : 'previa', oportunidades: ops, fontes: fontes };
}

// Execução agendada publica; qualquer outra (manual, teste) só gera a prévia.
function modoDaExecucao(modoN8n) {
  return modoN8n === 'trigger' || modoN8n === 'production' ? 'publicar' : 'previa';
}

// Confere o resultado que o publicador do servidor escreveu. Lança erro (que dispara o fluxo de alerta) se o
// arquivo não existe, não é JSON, é de outro pacote (resultado antigo) ou o status não é "ok".
function conferirResultado(texto, pacoteId) {
  if (!texto) throw new Error('BI: o servidor não escreveu o resultado da publicação (arquivo ausente ou vazio)');
  var r;
  try { r = JSON.parse(texto); } catch (e) { throw new Error('BI: resultado da publicação ilegível'); }
  if (!r || r.pacote_id !== pacoteId) throw new Error('BI: o resultado é de outro pacote (esperado ' + pacoteId + ', veio ' + (r && r.pacote_id) + '); o servidor não processou este pacote');
  if (r.status !== 'ok') throw new Error('BI: publicação recusada pelo servidor (a página anterior foi mantida): ' + (r.mensagem || 'sem mensagem'));
  return r;
}


const modo = modoDaExecucao(String($execution.mode || ''));
const agora = $now.setZone('America/Sao_Paulo');
const id = 'bi-' + agora.toFormat('yyyyLLddHHmmss') + '-' + String($execution.id || Math.floor(Math.random() * 1e6));
const pacote = montarPacote({
  oportunidades: $('Ler oportunidades aprovadas').all().map((i) => i.json || {}),
  fontes: $('Ler fontes').all().map((i) => i.json || {}),
  id, geradoEm: $now.toISO(), modo,
});
const binario = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(pacote), 'utf8'), 'pacote.json', 'application/json');
return [{ json: { pacote_id: id, modo, oportunidades: pacote.oportunidades.length, fontes: pacote.fontes.length }, binary: { data: binario } }];

